package config

import("context";"fmt";"os";"strconv";"strings")

// Config contains router onboarding settings.
type Config struct{OrganizationName,Validator,RootCA,DeviceCertificate,DeviceKey,Serial,Chassis,BoardID string;ValidatorPorts []int;AutoEnroll bool;RetryInitialMS,RetryMaxMS,ControllerTimeoutSeconds,ManagerTimeoutSeconds int}
// Load parses the small YAML subset used by the lab image.
func Load(ctx context.Context,path string)(Config,error){select{case<-ctx.Done():return Config{},ctx.Err();default:};b,e:=os.ReadFile(path);if e!=nil{return Config{},fmt.Errorf("read config: %w",e)};c:=Config{RetryInitialMS:250,RetryMaxMS:5000,ControllerTimeoutSeconds:5,ManagerTimeoutSeconds:5};for _,line:=range strings.Split(string(b),"\n"){line=strings.TrimSpace(line);if line==""||strings.HasPrefix(line,"#")||!strings.Contains(line,":"){continue};p:=strings.SplitN(line,":",2);k,v:=strings.TrimSpace(p[0]),strings.Trim(strings.TrimSpace(p[1]),"\"");switch k{case"organization":c.OrganizationName=v;case"validator":c.Validator=v;case"root_ca":c.RootCA=v;case"device_certificate":c.DeviceCertificate=v;case"device_key":c.DeviceKey=v;case"serial":c.Serial=v;case"chassis":c.Chassis=v;case"board_id":c.BoardID=v;case"auto_enroll":c.AutoEnroll=v=="true";case"retry_initial_ms":c.RetryInitialMS,_=strconv.Atoi(v);case"retry_max_ms":c.RetryMaxMS,_=strconv.Atoi(v);case"controller_timeout_seconds":c.ControllerTimeoutSeconds,_=strconv.Atoi(v);case"manager_timeout_seconds":c.ManagerTimeoutSeconds,_=strconv.Atoi(v);case"validator_ports":for _,s:=range strings.Split(strings.Trim(v,"[]"),","){if n,x:=strconv.Atoi(strings.TrimSpace(s));x==nil{c.ValidatorPorts=append(c.ValidatorPorts,n)}}}};if c.OrganizationName==""||c.Validator==""||c.RootCA==""||c.Serial==""||c.Chassis==""||c.BoardID==""{return Config{},fmt.Errorf("incomplete configuration")};if len(c.ValidatorPorts)==0{c.ValidatorPorts=[]int{12346,12347,12348}};return c,nil}
